  const rows = sort(getRows());

  return (
    <Table sortable aria-label="Table with controlled sort" style={{ minWidth: '500px' }}>
      <TableHeader>
        <TableRow>
          <TableHeaderCell {...headerSortProps('file')}>File</TableHeaderCell>
