import * as React from 'react';
import * as SharedContexts from '@fluentui/react-shared-contexts';

export type ContextLike<T = unknown> = React.Context<T>;

const moduleRecord = SharedContexts as unknown as Record<string, unknown>;

function isContextLike(value: unknown): value is ContextLike {
  return (
    typeof value === 'object' &&
    value !== null &&
    'Provider' in (value as object) &&
    'Consumer' in (value as object)
  );
}

/** Names in the module namespace that look like React contexts. */
export function listContextExports(): string[] {
  return Object.keys(moduleRecord).filter((key) => isContextLike(moduleRecord[key]));
}

/** Resolve a context by its exported name, or undefined when it is not a context. */
export function getContext<T>(name: string): ContextLike<T> | undefined {
  const candidate = moduleRecord[name];
  return isContextLike(candidate) ? (candidate as ContextLike<T>) : undefined;
}

console.log('context-like exports:', listContextExports());

import * as React from 'react';
import * as SharedContexts from '@fluentui/react-shared-contexts';

const moduleRecord = SharedContexts as unknown as Record<string, unknown>;
const FallbackContext = React.createContext<unknown>(undefined);

function isContextLike(value: unknown): value is React.Context<unknown> {
  return typeof value === 'object' && value !== null && 'Provider' in (value as object);
}

/**
 * Reads a shared context by export name. Never throws for a missing name:
 * it simply resolves to `undefined` through the fallback context.
 */
export function useOptionalSharedContext<T>(contextName: string): T | undefined {
  const candidate = moduleRecord[contextName];
  const context = isContextLike(candidate)
    ? (candidate as React.Context<T | undefined>)
    : (FallbackContext as React.Context<T | undefined>);

  return React.useContext(context);
}

export function StatusLabel(): JSX.Element {
  const value = useOptionalSharedContext<{ label?: string }>('SomeSharedContext');
  return <span>{value?.label ?? 'default'}</span>;
}

import * as React from 'react';
import * as SharedContexts from '@fluentui/react-shared-contexts';

const moduleRecord = SharedContexts as unknown as Record<string, unknown>;

function isContextLike(value: unknown): value is React.Context<unknown> {
  return typeof value === 'object' && value !== null && 'Provider' in (value as object);
}

export interface SharedContextBridgeProps<T> {
  contextName: string;
  value: T;
  children?: React.ReactNode;
}

export function SharedContextBridge<T>({
  contextName,
  value,
  children,
}: SharedContextBridgeProps<T>): JSX.Element {
  const candidate = moduleRecord[contextName];

  if (!isContextLike(candidate)) {
    throw new Error(
      `No context export named "${contextName}" was found on @fluentui/react-shared-contexts. ` +
        'Check the installed version and its type declarations.',
    );
  }

  const Context = candidate as React.Context<T>;
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

import * as React from 'react';
import * as SharedContexts from '@fluentui/react-shared-contexts';

const moduleRecord = SharedContexts as unknown as Record<string, unknown>;

function isContextLike(value: unknown): value is React.Context<unknown> {
  return typeof value === 'object' && value !== null && 'Provider' in (value as object);
}

interface AppDensityContextValue {
  density: 'compact' | 'comfortable' | 'spacious';
}

const AppDensityContext = React.createContext<AppDensityContextValue>({ density: 'comfortable' });

export const useAppDensity = (): AppDensityContextValue => React.useContext(AppDensityContext);

export interface DensityBridgeProps {
  contextName: string;
  children?: React.ReactNode;
}

export function DensityBridge({ contextName, children }: DensityBridgeProps): JSX.Element {
  const { density } = useAppDensity();

  const bridgedValue = React.useMemo(() => ({ density }), [density]);

  const candidate = moduleRecord[contextName];
  if (!isContextLike(candidate)) {
    return <>{children}</>;
  }

  const Context = candidate as React.Context<{ density: string }>;
  return <Context.Provider value={bridgedValue}>{children}</Context.Provider>;
}

import * as SharedContexts from '@fluentui/react-shared-contexts';

const moduleRecord = SharedContexts as unknown as Record<string, unknown>;

/**
 * Fails fast if an expected context export is missing from the resolved module.
 * Call this once during app bootstrap (or in a test setup file).
 */
export function assertSharedContexts(expected: readonly string[]): void {
  const missing = expected.filter((name) => !(name in moduleRecord));

  if (missing.length > 0) {
    throw new Error(
      `@fluentui/react-shared-contexts is missing expected export(s): ${missing.join(', ')}. ` +
        'Verify that exactly one copy of the package is installed and that its version ' +
        'matches the version required by the Fluent UI packages you use.',
    );
  }
}

