import * as React from 'react';

// Theme values are delivered as CSS custom properties on the themed surface.
// Replace the property names with the actual token names exposed by your
// installed version of @fluentui/react-theme.
const cardStyles: React.CSSProperties = {
  backgroundColor: 'var(--colorNeutralBackground1)',
  color: 'var(--colorNeutralForeground1)',
  border: '1px solid var(--colorNeutralStroke1)',
  borderRadius: 'var(--borderRadiusMedium)',
  padding: 'var(--spacingVerticalM) var(--spacingHorizontalM)',
};

export const Card = (props: { children?: React.ReactNode }) => (
  <div style={cardStyles}>{props.children}</div>
);

import * as React from 'react';

// A minimal, self-typed representation of a theme's value surface.
// Shape your real object after whichever exports your installed version of
// @fluentui/react-theme provides.
type ThemeValueMap = Record<`--${string}`, string>;

declare const brandThemeValues: ThemeValueMap;

export const ScopedTheme = (props: { children?: React.ReactNode }) => {
  const style = React.useMemo<React.CSSProperties>(() => {
    // Custom properties must be applied through a loosely typed bag.
    return brandThemeValues as unknown as React.CSSProperties;
  }, []);

  return <div style={style}>{props.children}</div>;
};

type TokenName = string;

/**
 * Resolve a theme token name to a CSS custom property reference.
 * The theme package supplies the values; the naming convention for the
 * custom properties should be confirmed against the installed version.
 */
export const token = (name: TokenName): string => `var(--${name})`;

// Usage inside a component's style object
const toolbarStyles = {
  display: 'flex',
  gap: token('spacingHorizontalS'),
  backgroundColor: token('colorNeutralBackground2'),
};

export const toolbarClassName = 'toolbar';

// Pair with a stylesheet that applies the object, e.g. via a CSS-in-JS
// renderer or `Object.assign(element.style, toolbarStyles)`.

export const readThemeValue = (
  element: HTMLElement,
  cssVariableName: string,
  fallback: string = '',
): string => {
  if (typeof window === 'undefined') {
    // Server-side rendering / Node test environments have no computed styles.
    return fallback;
  }
  const value = window
    .getComputedStyle(element)
    .getPropertyValue(cssVariableName)
    .trim();
  return value.length > 0 ? value : fallback;
};

// Example: resolve a themed color for a chart library that needs a literal.
declare const chartContainer: HTMLElement;
const stroke = readThemeValue(chartContainer, '--colorBrandBackground', '#0f6cbd');

