import * as React from 'react';
import {
  Badge,
  Button,
  Progress,
  Spinner,
  Text,
  Tooltip,
} from '@fluentui/react-components';

export const SaveBar: React.FC = () => {
  const [saving, setSaving] = React.useState(false);
  const [progress, setProgress] = React.useState(0);

  const startSaving = () => {
    setSaving(true);
    setProgress(0);

    const timer = window.setInterval(() => {
      setProgress((current) => {
        const next = current + 25;
        if (next >= 100) {
          window.clearInterval(timer);
          setSaving(false);
          return 100;
        }
        return next;
      });
    }, 400);
  };

  return (
    <div style={{ display: 'grid', gap: 12, maxWidth: 420 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        {saving ? (
          <Spinner size="tiny" label="Saving changes" labelPosition="after" />
        ) : (
          <Badge appearance="tint" color="success">
            All changes saved
          </Badge>
        )}
      </div>

      <Progress
        value={progress}
        max={100}
        shape="rounded"
        thickness="medium"
        color={progress === 100 ? 'success' : 'brand'}
      />

      <Text size={200}>
        {progress}% complete
      </Text>

      <div style={{ display: 'flex', gap: 8 }}>
        <Button appearance="primary" disabled={saving} onClick={startSaving}>
          Save
        </Button>

        <Tooltip
          content="You need the Editor role to publish this document"
          relationship="description"
          showDelay={200}
          withArrow
        >
          <Button appearance="secondary" disabledFocusable>
            Publish
          </Button>
        </Tooltip>
      </div>
    </div>
  );
};

export default SaveBar;

