type ContactStepId = 'details' | 'message' | 'confirm';

type ContactValues = {
  fullName: string;
  email: string;
  topic: string;
  message: string;
  consent: boolean;
};

const CONTACT_STEPS: WizardStepDefinition<ContactStepId>[] = [
  { id: 'details', title: 'Your details' },
  { id: 'message', title: 'Your message' },
  { id: 'confirm', title: 'Confirm' },
];

const CONTACT_INITIAL_VALUES: ContactValues = {
  fullName: '',
  email: '',
  topic: 'sales',
  message: '',
  consent: false,
};

function validateContactStep(stepId: ContactStepId, values: ContactValues): Record<string, string> {
  const errors: Record<string, string> = {};

  if (stepId === 'details') {
    if (!values.fullName.trim()) {
      errors.fullName = 'Tell us your name.';
    }
    if (!values.email.trim()) {
      errors.email = 'We need an email address to reply.';
    } else if (!values.email.includes('@')) {
      errors.email = 'That email address does not look right.';
    }
  }

  if (stepId === 'message' && values.message.trim().length < 20) {
    errors.message = 'Please give us at least 20 characters.';
  }

  if (stepId === 'confirm' && !values.consent) {
    errors.consent = 'Please confirm before sending.';
  }

  return errors;
}

export const ContactWizard = () => {
  const [values, setValues] = React.useState<ContactValues>(CONTACT_INITIAL_VALUES);
  const [status, setStatus] = React.useState<'editing' | 'sending' | 'sent'>('editing');

  const wizard = useWizard<ContactStepId, ContactValues>({
    steps: CONTACT_STEPS,
    values,
    validateStep: validateContactStep,
  });

  const updateField = (patch: Partial<ContactValues>) => {
    setValues(previous => ({ ...previous, ...patch }));
    Object.keys(patch).forEach(key => wizard.clearError(key));
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!wizard.validateAll()) {
      return;
    }
    setStatus('sending');
    window.setTimeout(() => setStatus('sent'), 800);
  };

  if (status === 'sent') {
    return (
      <Card appearance='outline' style={{ maxWidth: 560, margin: '0 auto', padding: 24, display: 'flex', flexDirection: 'column', gap: 12 }}>
        <Text size={400} weight='semibold'>Thanks, {values.fullName}</Text>
        <Text>{`We received your message and will reply to ${values.email} shortly.`}</Text>
        <div>
          <Button
            appearance='primary'
            onClick={() => {
              setValues(CONTACT_INITIAL_VALUES);
              setStatus('editing');
              wizard.goTo(0);
            }}
          >
            Send another message
          </Button>
        </div>
      </Card>
    );
  }

  return (
    <Card appearance='outline' style={{ maxWidth: 560, margin: '0 auto', padding: 24 }}>
      <form noValidate onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <StepIndicator steps={CONTACT_STEPS} currentIndex={wizard.stepIndex} />
        <Divider />
        <Text size={400} weight='semibold'>{wizard.step.title}</Text>

        {wizard.step.id === 'details' && (
          <>
            <Field
              label='Full name'
              required
              validationState={wizard.errors.fullName ? 'error' : 'none'}
              validationMessage={wizard.errors.fullName}
            >
              <Input value={values.fullName} onChange={(_, data) => updateField({ fullName: data.value })} />
            </Field>
            <Field
              label='Email'
              required
              validationState={wizard.errors.email ? 'error' : 'none'}
              validationMessage={wizard.errors.email}
            >
              <Input type='email' value={values.email} onChange={(_, data) => updateField({ email: data.value })} />
            </Field>
          </>
        )}

        {wizard.step.id === 'message' && (
          <>
            <Field label='Topic' required>
              <Select value={values.topic} onChange={(_, data) => updateField({ topic: data.value })}>
                <option value='sales'>Sales</option>
                <option value='support'>Support</option>
                <option value='partnership'>Partnership</option>
              </Select>
            </Field>
            <Field
              label='Message'
              required
              hint='At least 20 characters.'
              validationState={wizard.errors.message ? 'error' : 'none'}
              validationMessage={wizard.errors.message}
            >
              <Textarea
                value={values.message}
                onChange={(_, data) => updateField({ message: data.value })}
                resize='vertical'
              />
            </Field>
          </>
        )}

        {wizard.step.id === 'confirm' && (
          <>
            <MessageBar intent='info'>
              {`We will reply to ${values.email || 'the email address you provide'}.`}
            </MessageBar>
            <Field
              validationState={wizard.errors.consent ? 'error' : 'none'}
              validationMessage={wizard.errors.consent}
            >
              <Checkbox
                label='I agree to be contacted about my request'
                checked={values.consent}
                onChange={(_, data) => updateField({ consent: data.checked === true })}
              />
            </Field>
          </>
        )}

        <Divider />

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
          <Button
            type='button'
            appearance='secondary'
            onClick={wizard.goBack}
            disabled={wizard.isFirstStep || status === 'sending'}
          >
            Back
          </Button>
          {wizard.isLastStep ? (
            <Button type='submit' appearance='primary' disabled={status === 'sending'}>
              {status === 'sending' ? 'Sending' : 'Send message'}
            </Button>
          ) : (
            <Button type='button' appearance='primary' onClick={wizard.goNext}>
              Next
            </Button>
          )}
        </div>
      </form>
    </Card>
  );
};

import * as React from 'react';
import { Button, Card, Field, Input, MessageBar, Spinner, Text } from '@fluentui/react-components';

type Availability = 'idle' | 'checking' | 'available' | 'taken';

const MIN_PASSWORD_LENGTH = 12;

/** Stand-in for a real availability endpoint. Emails ending in contoso.com are treated as taken. */
function checkEmailAvailability(email: string): Promise<boolean> {
  return new Promise<boolean>(resolve => {
    window.setTimeout(() => resolve(!email.toLowerCase().endsWith('@contoso.com')), 700);
  });
}

export const StepWithAsyncValidation = () => {
  const [email, setEmail] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [availability, setAvailability] = React.useState<Availability>('idle');
  const [takenMessage, setTakenMessage] = React.useState<string | undefined>(undefined);
  const [completed, setCompleted] = React.useState(false);
  const latestRequest = React.useRef(0);

  const handleEmailChange = (nextEmail: string) => {
    setEmail(nextEmail);
    setCompleted(false);
    setTakenMessage(undefined);

    const requestId = latestRequest.current + 1;
    latestRequest.current = requestId;

    if (!nextEmail.includes('@')) {
      setAvailability('idle');
      return;
    }

    setAvailability('checking');

    checkEmailAvailability(nextEmail).then(isAvailable => {
      // A newer keystroke already started the check that matters, so drop this response.
      if (requestId !== latestRequest.current) {
        return;
      }
      setAvailability(isAvailable ? 'available' : 'taken');
      if (!isAvailable) {
        setTakenMessage('That email is already registered. Try signing in instead.');
      }
    });
  };

  const isEmailValid = availability === 'available';
  const passwordTooShort = password.length > 0 && password.length < MIN_PASSWORD_LENGTH;
  const isPasswordValid = password.length >= MIN_PASSWORD_LENGTH;
  const canContinue = isEmailValid && isPasswordValid;

  const emailValidationState = takenMessage ? 'error' : isEmailValid ? 'success' : 'none';
  const emailValidationMessage =
    takenMessage ?? (isEmailValid ? 'That email address is available.' : undefined);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canContinue) {
      return;
    }
    setCompleted(true);
  };

  return (
    <Card appearance='outline' style={{ maxWidth: 480, margin: '0 auto', padding: 24 }}>
      <form noValidate onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <Text size={400} weight='semibold'>Step 1 of 3 - Account</Text>
          <Text size={200}>We check the email address against the server while you type.</Text>
        </div>

        <Field
          label='Work email'
          required
          hint='Availability is checked automatically.'
          validationState={emailValidationState}
          validationMessage={emailValidationMessage}
        >
          <Input
            type='email'
            value={email}
            onChange={(_, data) => handleEmailChange(data.value)}
            contentAfter={
              availability === 'checking'
                ? <Spinner size='extra-tiny' aria-label='Checking availability' />
                : undefined
            }
          />
        </Field>

        <Field
          label='Password'
          required
          hint={`At least ${MIN_PASSWORD_LENGTH} characters.`}
          validationState={passwordTooShort ? 'warning' : 'none'}
          validationMessage={passwordTooShort ? `Use at least ${MIN_PASSWORD_LENGTH} characters.` : undefined}
        >
          <Input type='password' value={password} onChange={(_, data) => setPassword(data.value)} />
        </Field>

        {completed && (
          <MessageBar intent='success'>Account step complete. Continue to the next step.</MessageBar>
        )}

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 12 }}>
          {availability === 'checking' && <Spinner size='tiny' label='Checking email' labelPosition='after' />}
          <Button type='submit' appearance='primary' disabled={!canContinue}>
            Continue
          </Button>
        </div>
      </form>
    </Card>
  );
};

import * as React from "react";
import {
  Button,
  Checkbox,
  Field,
  Input,
  MessageBar,
  Select,
  Text,
  Textarea,
} from "@fluentui/react-components";

type FormValues = {
  fullName: string;
  email: string;
  plan: string;
  bio: string;
  acceptTerms: boolean;
};

type FieldName = keyof FormValues;
type FormErrors = Partial<Record<FieldName, string>>;

const initialValues: FormValues = {
  fullName: "",
  email: "",
  plan: "",
  bio: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FormErrors {
  const errors: FormErrors = {};

  if (values.fullName.trim().length === 0) {
    errors.fullName = "Enter your full name.";
  } else if (values.fullName.trim().length < 2) {
    errors.fullName = "Use at least 2 characters.";
  }

  if (values.email.trim().length === 0) {
    errors.email = "Enter your email address.";
  } else if (!EMAIL_PATTERN.test(values.email.trim())) {
    errors.email = "Enter an address like name@example.com.";
  }

  if (values.plan.length === 0) {
    errors.plan = "Choose a plan to continue.";
  }

  if (values.bio.length > 200) {
    errors.bio = `Shorten your bio by ${values.bio.length - 200} characters.`;
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "Accept the terms to create your account.";
  }

  return errors;
}

export const SignUpForm: React.FC = () => {
  const [values, setValues] = React.useState<FormValues>(initialValues);
  const [touched, setTouched] = React.useState<Partial<Record<FieldName, boolean>>>({});
  const [submitAttempted, setSubmitAttempted] = React.useState(false);
  const [isSubmitting, setIsSubmitting] = React.useState(false);

  // Errors are derived from values on every render, so they can never drift out of sync.
  const errors = validate(values);
  const errorCount = Object.keys(errors).length;

  const visibleError = (name: FieldName): string | undefined =>
    touched[name] || submitAttempted ? errors[name] : undefined;

  const validationStateFor = (name: FieldName): "error" | "none" =>
    visibleError(name) ? "error" : "none";

  function setField<K extends FieldName>(name: K, value: FormValues[K]) {
    setValues(previous => {
      const next: FormValues = { ...previous };
      next[name] = value;
      return next;
    });
  }

  function markTouched(name: FieldName) {
    setTouched(previous => {
      const next = { ...previous };
      next[name] = true;
      return next;
    });
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitAttempted(true);

    if (errorCount > 0) {
      // Per-field messages and the summary are visible now; focus the first invalid control here.
      return;
    }

    setIsSubmitting(true);
    try {
      await new Promise(resolve => window.setTimeout(resolve, 600)); // replace with your API call
      setValues(initialValues);
      setTouched({});
      setSubmitAttempted(false);
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate style={{ display: "grid", gap: 16, maxWidth: 480 }}>
      {submitAttempted && errorCount > 0 ? (
        <MessageBar intent="error" politeness="assertive">
          <Text weight="semibold">
            {errorCount === 1
              ? "1 field needs your attention."
              : `${errorCount} fields need your attention.`}
          </Text>
        </MessageBar>
      ) : null}

      <Field
        label="Full name"
        required
        validationState={validationStateFor("fullName")}
        validationMessage={visibleError("fullName")}
        hint="Use the name that should appear on your invoices."
      >
        <Input
          value={values.fullName}
          onChange={(ev, data) => setField("fullName", data.value)}
          onBlur={() => markTouched("fullName")}
          autoComplete="name"
        />
      </Field>

      <Field
        label="Email"
        required
        validationState={validationStateFor("email")}
        validationMessage={visibleError("email")}
      >
        <Input
          type="email"
          value={values.email}
          onChange={(ev, data) => setField("email", data.value)}
          onBlur={() => markTouched("email")}
          autoComplete="email"
        />
      </Field>

      <Field
        label="Plan"
        required
        validationState={validationStateFor("plan")}
        validationMessage={visibleError("plan")}
      >
        <Select
          value={values.plan}
          onChange={(ev, data) => setField("plan", data.value)}
          onBlur={() => markTouched("plan")}
        >
          <option value="" disabled>
            Choose a plan
          </option>
          <option value="starter">Starter</option>
          <option value="team">Team</option>
          <option value="enterprise">Enterprise</option>
        </Select>
      </Field>

      <Field
        label="Bio"
        validationState={validationStateFor("bio")}
        validationMessage={visibleError("bio")}
        hint={`${values.bio.length}/200 characters`}
      >
        <Textarea
          value={values.bio}
          resize="vertical"
          onChange={(ev, data) => setField("bio", data.value)}
          onBlur={() => markTouched("bio")}
        />
      </Field>

      <Field
        validationState={validationStateFor("acceptTerms")}
        validationMessage={visibleError("acceptTerms")}
      >
        <Checkbox
          checked={values.acceptTerms}
          label="I accept the terms of service"
          onChange={(ev, data) => setField("acceptTerms", data.checked === true)}
          onBlur={() => markTouched("acceptTerms")}
        />
      </Field>

      <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
        <Button
          type="button"
          appearance="secondary"
          onClick={() => {
            setValues(initialValues);
            setTouched({});
            setSubmitAttempted(false);
          }}
        >
          Reset
        </Button>
        <Button type="submit" appearance="primary" disabled={isSubmitting}>
          {isSubmitting ? "Creating account..." : "Create account"}
        </Button>
      </div>
    </form>
  );
};

import * as React from "react";
import { Field, Input, Spinner } from "@fluentui/react-components";

type AvailabilityStatus = "idle" | "checking" | "available" | "taken" | "unknown";

const TAKEN_USERNAMES = new Set(["admin", "support", "fluent", "test"]);

function checkUsernameAvailable(username: string): Promise<boolean> {
  return new Promise(resolve => {
    window.setTimeout(() => resolve(!TAKEN_USERNAMES.has(username.toLowerCase())), 500);
  });
}

export const UsernameField: React.FC = () => {
  const [value, setValue] = React.useState("");
  const [status, setStatus] = React.useState<AvailabilityStatus>("idle");

  const username = value.trim();
  const isTooShort = username.length > 0 && username.length < 3;

  React.useEffect(() => {
    if (username.length < 3) {
      setStatus("idle");
      return;
    }

    let cancelled = false;
    setStatus("checking");

    const timer = window.setTimeout(() => {
      checkUsernameAvailable(username)
        .then(available => {
          if (!cancelled) {
            setStatus(available ? "available" : "taken");
          }
        })
        .catch(() => {
          if (!cancelled) {
            setStatus("unknown");
          }
        });
    }, 300);

    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [username]);

  const validationState: "error" | "warning" | "success" | "none" =
    isTooShort || status === "taken"
      ? "error"
      : status === "unknown"
        ? "warning"
        : status === "available"
          ? "success"
          : "none";

  const validationMessage = isTooShort
    ? "Use at least 3 characters."
    : status === "taken"
      ? "That username is already taken."
      : status === "unknown"
        ? "We could not check availability. Try again."
        : status === "available"
          ? "This username is available."
          : undefined;

  return (
    <Field
      label="Username"
      required
      validationState={validationState}
      validationMessage={validationMessage}
      hint="Letters, numbers and underscores only."
    >
      <Input
        value={value}
        autoComplete="username"
        onChange={(ev, data) => setValue(data.value.replace(/[^a-zA-Z0-9_]/g, ""))}
        contentAfter={status === "checking" ? <Spinner size="extra-tiny" /> : undefined}
      />
    </Field>
  );
};

import * as React from "react";
import {
  Button,
  Field,
  Input,
  MessageBar,
  Text,
} from "@fluentui/react-components";

type SupportedInputType = "text" | "email" | "password" | "search" | "tel" | "url";

type ValidatedTextFieldProps = {
  label: string;
  value: string;
  onChange: (value: string) => void;
  onBlur: () => void;
  error?: string;
  hint?: string;
  required?: boolean;
  type?: SupportedInputType;
  autoComplete?: string;
};

export const ValidatedTextField: React.FC<ValidatedTextFieldProps> = ({
  label,
  value,
  onChange,
  onBlur,
  error,
  hint,
  required,
  type = "text",
  autoComplete,
}) => (
  <Field
    label={label}
    required={required}
    hint={hint}
    validationState={error ? "error" : "none"}
    validationMessage={error}
  >
    <Input
      type={type}
      value={value}
      autoComplete={autoComplete}
      onChange={(ev, data) => onChange(data.value)}
      onBlur={onBlur}
    />
  </Field>
);

type PasswordValues = {
  current: string;
  next: string;
  confirm: string;
};

type PasswordField = keyof PasswordValues;
type PasswordErrors = Partial<Record<PasswordField, string>>;

function validatePasswords(values: PasswordValues): PasswordErrors {
  const errors: PasswordErrors = {};

  if (values.current.length === 0) {
    errors.current = "Enter your current password.";
  }

  if (values.next.length < 12) {
    errors.next = "Use at least 12 characters.";
  } else if (!/[0-9]/.test(values.next)) {
    errors.next = "Add at least one number.";
  } else if (!/[^A-Za-z0-9]/.test(values.next)) {
    errors.next = "Add at least one symbol.";
  }

  if (values.confirm.length === 0) {
    errors.confirm = "Re-enter the new password.";
  } else if (values.confirm !== values.next) {
    errors.confirm = "Passwords do not match.";
  }

  return errors;
}

export const ChangePasswordForm: React.FC = () => {
  const [values, setValues] = React.useState<PasswordValues>({
    current: "",
    next: "",
    confirm: "",
  });
  const [touched, setTouched] = React.useState<Partial<Record<PasswordField, boolean>>>({});
  const [submitAttempted, setSubmitAttempted] = React.useState(false);
  const [saved, setSaved] = React.useState(false);

  // Cross-field rules are just part of the same derived validation pass.
  const errors = validatePasswords(values);
  const isValid = Object.keys(errors).length === 0;

  const visibleError = (name: PasswordField): string | undefined =>
    touched[name] || submitAttempted ? errors[name] : undefined;

  function setField<K extends PasswordField>(name: K, value: string) {
    setValues(previous => {
      const next: PasswordValues = { ...previous };
      next[name] = value;
      return next;
    });
    setSaved(false);
  }

  function markTouched(name: PasswordField) {
    setTouched(previous => {
      const next = { ...previous };
      next[name] = true;
      return next;
    });
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitAttempted(true);

    if (!isValid) {
      return;
    }

    await new Promise(resolve => window.setTimeout(resolve, 500)); // replace with your API call
    setSaved(true);
    setValues({ current: "", next: "", confirm: "" });
    setTouched({});
    setSubmitAttempted(false);
  }

  return (
    <form onSubmit={handleSubmit} noValidate style={{ display: "grid", gap: 16, maxWidth: 420 }}>
      <ValidatedTextField
        label="Current password"
        type="password"
        required
        autoComplete="current-password"
        value={values.current}
        onChange={value => setField("current", value)}
        onBlur={() => markTouched("current")}
        error={visibleError("current")}
      />

      <ValidatedTextField
        label="New password"
        type="password"
        required
        autoComplete="new-password"
        hint="At least 12 characters, with a number and a symbol."
        value={values.next}
        onChange={value => setField("next", value)}
        onBlur={() => markTouched("next")}
        error={visibleError("next")}
      />

      <ValidatedTextField
        label="Confirm new password"
        type="password"
        required
        autoComplete="new-password"
        value={values.confirm}
        onChange={value => setField("confirm", value)}
        onBlur={() => markTouched("confirm")}
        error={visibleError("confirm")}
      />

      {saved ? (
        <MessageBar intent="success" politeness="polite">
          <Text>Your password was updated.</Text>
        </MessageBar>
      ) : null}

      <div>
        <Button type="submit" appearance="primary">
          Change password
        </Button>
      </div>
    </form>
  );
};

