} from "@fluentui/react-components";

interface RenameDialogProps {
  currentName: string;
  onRename: (nextName: string) => Promise<void>;
}

export const RenameDialog: React.FC<RenameDialogProps> = ({ currentName, onRename }) => {
  const [open, setOpen] = React.useState(false);
  const [name, setName] = React.useState(currentName);
  const [error, setError] = React.useState<string>();
  const [pending, setPending] = React.useState(false);
  const [confirmDiscard, setConfirmDiscard] = React.useState(false);

  const dirty = name.trim() !== currentName;

  const closeAndReset = () => {
    setOpen(false);
    setName(currentName);
    setError(undefined);
    setConfirmDiscard(false);
    setPending(false);
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const nextName = name.trim();
    if (!nextName) {
      setError("Enter a name.");
      return;
    }
    if (nextName === currentName) {
      closeAndReset();
      return;
    }

    setPending(true);
    try {
      await onRename(nextName);
      closeAndReset();
    } catch {
      setError("The new name could not be saved. Try again.");
      setPending(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(_event, data) => {
        if (data.open) {
          setOpen(true);
          return;
        }
        if (pending) {
          return; // never dismiss while saving
        }
        if (dirty) {
          setConfirmDiscard(true); // keep the dialog open and ask first
          return;
        }
        closeAndReset();
      }}
    >
      <DialogTrigger disableButtonEnhancement>
        <Button>Rename</Button>
      </DialogTrigger>
      <DialogSurface>
        <form onSubmit={handleSubmit} noValidate>
          <DialogBody>
            <DialogTitle>Rename item</DialogTitle>
            <DialogContent>
              <Field
                label="Name"
                required
                hint={`Current name: ${currentName}`}
                validationState={error ? "error" : "none"}
                validationMessage={error}
              >
                <Input
                  value={name}
                  onChange={(_event, data) => {
                    setName(data.value);
                    setError(undefined);
                  }}
                />
              </Field>

              {confirmDiscard && (
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: "12px",
                    marginTop: "12px",
                  }}
                >
                  <span>You have unsaved changes. Close without saving?</span>
                  <span style={{ display: "flex", gap: "8px" }}>
                    <Button
                      appearance="secondary"
                      type="button"
                      size="small"
                      onClick={() => setConfirmDiscard(false)}
                    >
                      Keep editing
                    </Button>
                    <Button appearance="primary" type="button" size="small" onClick={closeAndReset}>
                      Discard
                    </Button>
                  </span>
                </div>
              )}
            </DialogContent>
            <DialogActions>
              {/* Cancel uses DialogTrigger, so it flows through the same guard as Escape. */}
              <DialogTrigger disableButtonEnhancement>
                <Button appearance="secondary" type="button" disabled={pending}>
                  Cancel
                </Button>
              </DialogTrigger>
              <Button appearance="primary" type="submit" disabled={pending}>
                Save
              </Button>
            </DialogActions>
          </DialogBody>
        </form>
      </DialogSurface>
    </Dialog>
  );
};

