import * as React from 'react';
import {
  Avatar,
  Badge,
  Button,
  Card,
  Text,
  makeStyles,
  tokens,
} from '@fluentui/react-components';

type ProjectStatus = 'On track' | 'At risk' | 'Blocked';

interface Project {
  id: string;
  name: string;
  description: string;
  owner: string;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  {
