    alignItems: 'center',
    columnGap: tokens.spacingHorizontalS,
    minWidth: 0,
  },
});

const badgeColor = (status: ProjectStatus): 'success' | 'warning' | 'danger' => {
  if (status === 'On track') {
    return 'success';
  }
  if (status === 'At risk') {
    return 'warning';
  }
  return 'danger';
};

export const ResponsiveProjectGrid: React.FC = () => {
  const styles = useStyles();

