}

const NAV_ITEMS = ['Overview', 'Deployments', 'Analytics', 'Settings'] as const;

const STATS = [
  { id: 'deploys', label: 'Deployments today', value: '18' },
  { id: 'failed', label: 'Failed checks', value: '2' },
  { id: 'build', label: 'Average build time', value: '4m 12s' },
